@import "@fontsource-variable/inter";
@import "@fontsource-variable/instrument-sans";
@import "@fontsource-variable/newsreader/opsz.css";
@import "@fontsource/commit-mono";

/* Light: the sibling. A white page, graphite ink, cool grey copy, black-ink hairlines,
   the violet a step deeper so it reads on white. */
:root {
  --background: oklch(1 0 0);
  --foreground: oklch(0.2 0.004 250);
  --card: oklch(0.985 0.002 250);
  --card-foreground: oklch(0.2 0.004 250);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.2 0.004 250);
  --primary: oklch(0.2 0.004 250);
  --primary-foreground: oklch(0.985 0 0);
  --secondary: oklch(0.965 0.003 250);
  --secondary-foreground: oklch(0.2 0.004 250);
  --muted: oklch(0.955 0.004 250);
  --muted-foreground: oklch(0.5 0.008 240);
  --accent: oklch(0.94 0.006 250);
  --accent-foreground: oklch(0.2 0.004 250);
  --destructive: oklch(0.58 0.22 22);
  --destructive-foreground: oklch(0.985 0 0);
  --border: oklch(0.3 0.02 250 / 14%);
  --input: oklch(0.3 0.02 250 / 18%);
  --ring: oklch(0.55 0.19 285);
  --highlight: oklch(0.55 0.19 285);
  --highlight-foreground: oklch(0.985 0 0);
  --glow: oklch(0.45 0.02 250);
  --chart-1: oklch(0.6 0.16 250);
  --chart-2: oklch(0.62 0.17 155);
  --chart-3: oklch(0.7 0.16 65);
  --chart-4: oklch(0.55 0.19 285);
  --chart-5: oklch(0.65 0.13 200);
  --sidebar: oklch(0.985 0.002 250);
  --sidebar-foreground: oklch(0.2 0.004 250);
  --sidebar-primary: oklch(0.2 0.004 250);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.94 0.006 250);
  --sidebar-accent-foreground: oklch(0.2 0.004 250);
  --sidebar-border: oklch(0.3 0.02 250 / 14%);
  --sidebar-ring: oklch(0.55 0.19 285);

  --typeface-body: "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Instrument Sans Variable", "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "Commit Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 1rem;
  --page-width: 80rem;
  --page-gutter: 1.5rem;
  --section-y: 6rem;

  /* theme-only: the display serif of the hero and closing titles (Domaine Display stand-in) */
  --resend-serif: "Newsreader Variable", ui-serif, Georgia, serif;
}

/* Dark: the faithful mode. Pure black page, #f0f0f0 ink, #a1a4a5 copy, cool-white hairlines
   at 19%, graphite cards (#141517), lilac-violet #9281f7, white glows. */
.dark {
  --background: oklch(0 0 0);
  --foreground: oklch(0.955 0 0);
  --card: oklch(0.195 0.004 260);
  --card-foreground: oklch(0.955 0 0);
  --popover: oklch(0.16 0.004 260);
  --popover-foreground: oklch(0.955 0 0);
  --primary: oklch(0.985 0 0);
  --primary-foreground: oklch(0 0 0);
  --secondary: oklch(0.225 0 0);
  --secondary-foreground: oklch(0.955 0 0);
  --muted: oklch(0.2 0.004 260);
  --muted-foreground: oklch(0.71 0.004 220);
  --accent: oklch(0.82 0.03 240 / 14%);
  --accent-foreground: oklch(0.955 0 0);
  --destructive: oklch(0.65 0.23 20);
  --destructive-foreground: oklch(0.985 0 0);
  --border: oklch(0.93 0.025 245 / 19%);
  --input: oklch(0.93 0.025 245 / 15%);
  --ring: oklch(0.66 0.17 285);
  --highlight: oklch(0.66 0.17 285);
  --highlight-foreground: oklch(0 0 0);
  --glow: oklch(0.92 0.01 250);
  --chart-1: oklch(0.72 0.14 250);
  --chart-2: oklch(0.86 0.2 158);
  --chart-3: oklch(0.72 0.18 60);
  --chart-4: oklch(0.66 0.17 285);
  --chart-5: oklch(0.8 0.14 200);
  --sidebar: oklch(0.1 0.002 260);
  --sidebar-foreground: oklch(0.955 0 0);
  --sidebar-primary: oklch(0.985 0 0);
  --sidebar-primary-foreground: oklch(0 0 0);
  --sidebar-accent: oklch(0.82 0.03 240 / 14%);
  --sidebar-accent-foreground: oklch(0.955 0 0);
  --sidebar-border: oklch(0.93 0.025 245 / 19%);
  --sidebar-ring: oklch(0.66 0.17 285);
}
